'use strict';
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pathIsArticle = /\/article\.html$/.test(location.pathname);
const texts={en:{eyebrow:'THE END PRODUCT · OPEN SCIENTIFIC LITERATURE',heroTitle:'Research that can <em>be read, examined and built upon.</em>',heroDesc:'An open scholarly record where evidence, peer review and later impact are shown separately. Explore the finished publication experience.',browseBtn:'Explore the research library →',featuredBtn:'View a complete article ↗',proof:'Full text and PDF · Transparent reviews · Versions and continuing assessment',strip1:'Discoverable research',strip2:'Evidence-based certification',strip3:'Continuous post-publication review',recordLabel:'THE PUBLIC RESEARCH RECORD',libraryTitle:'Explore published research',libraryDesc:'Search a multidisciplinary collection, distinguish preliminary preprints from expert-certified research, and inspect the full evaluation record.',all:'All records',certified:'Illustratively certified',preprint:'Preprints',privacy:'Public records here are synthetic demonstrations only. Manuscripts uploaded through the portal are stored privately in the <strong>jus</strong> repository. The demonstration never retrieves, exposes or publishes those private files.',upload:'Visit submission portal ↗',frameworkTitle:'What distinguishes this publishing model?',f1title:'Publication status',f1copy:'A manuscript may be openly available without claiming peer-review certification.',f2title:'Scientific reliability',f2copy:'Reviewers assess methods, evidence quality and reproducibility, with documented limitations.',f3title:'Impact over time',f3copy:'Citations, replication and expert commentary inform impact without automatically altering reliability.',awardOver:'RECOGNITION BEYOND PUBLICATION',awardTitle:'Annual Research Excellence Awards',awardCopy:'The proposed hub could honor ten outstanding contributions each year, recognizing rigorous science, replicability and societal value, without using citation counts as a substitute for scientific reliability. <strong>No awards have yet been granted.</strong>',awardLink:'Explore the proposed awards ↗',back:'All research publications'},ar:{eyebrow:'المنتج النهائي · الأدبيات العلمية المفتوحة',heroTitle:'أبحاث يمكن <em>قراءتها وتقييمها والبناء عليها.</em>',heroDesc:'سجل علمي مفتوح يفصل بوضوح بين الأدلة والتحكيم العلمي والأثر اللاحق. استكشف تجربة النشر النهائية.',browseBtn:'استعرض مكتبة الأبحاث ←',featuredBtn:'شاهد مقالة متكاملة ↗',proof:'النص الكامل وPDF · مراجعات شفافة · إصدارات وتقييم مستمر',strip1:'أبحاث قابلة للاكتشاف',strip2:'اعتماد مبني على الأدلة',strip3:'مراجعة علمية مستمرة بعد النشر',recordLabel:'السجل العلمي المفتوح',libraryTitle:'استعرض الأبحاث المنشورة',libraryDesc:'ابحث في مجموعة متعددة التخصصات وميّز المسودات الأولية عن الأبحاث المعتمدة وتعرّف إلى سجل التقييم كاملاً.',all:'جميع السجلات',certified:'اعتماد توضيحي',preprint:'مسودات أولية',privacy:'السجلات العامة هنا افتراضية لأغراض العرض فقط. المخطوطات المرفوعة عبر البوابة محفوظة في المستودع الخاص <strong>jus</strong>. لا يجري هذا العرض سحب أو كشف أو نشر تلك الملفات.',upload:'انتقل إلى بوابة التقديم ↗',frameworkTitle:'ما الذي يميز نموذج النشر هذا؟',f1title:'حالة النشر',f1copy:'يمكن إتاحة المخطوطة دون الادعاء بأنها خضعت للتحكيم.',f2title:'الموثوقية العلمية',f2copy:'يقيم المحكمون المنهجية وجودة الأدلة وقابلية التكرار ويوثقون القيود.',f3title:'الأثر عبر الزمن',f3copy:'تفيد الاستشهادات والتكرارات وملاحظات الخبراء في تقييم الأثر دون تغيير تلقائي لدرجة الموثوقية.',awardOver:'التقدير العلمي بعد النشر',awardTitle:'جوائز التميز البحثي السنوية',awardCopy:'يمكن للمشروع أن يكرّم سنوياً عشرة بحوث رائدة، تقديراً للصرامة العلمية وقابلية التكرار والفائدة المجتمعية. لا تحل الاستشهادات محل التقييم العلمي. <strong>لم تُمنح أي جوائز بعد.</strong>',awardLink:'تعرّف إلى الجوائز المقترحة ↗',back:'جميع المنشورات العلمية'}};
// Optional preferences must not prevent public article pages loading.
function readSetting(key){try{return window.localStorage.getItem(key);}catch(error){console.warn('Preference storage unavailable:',key);return null;}}
function saveSetting(key,value){try{window.localStorage.setItem(key,value);}catch(error){console.warn('Preference not persisted:',key);}}
let lang=readSetting('uj-pub-lang')==='ar'?'ar':'en',dark=readSetting('uj-pub-theme')==='dark',papers=[];
const t=x=>texts[lang][x]||x;
const label=(en,ar)=>lang==='ar'?ar:en;
function setUI(){
 try{
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  document.body.classList.toggle('dark',dark);
  document.documentElement.dataset.colorMode=dark?'dark':'light';
  const langBtn=document.getElementById('language');if(langBtn)langBtn.textContent=lang==='ar'?'English':'العربية';
  const themeBtn=document.getElementById('theme');if(themeBtn){themeBtn.textContent=dark?'☀':'☾';themeBtn.setAttribute('aria-pressed',String(dark));}
  document.querySelectorAll('[data-t]').forEach(el=>{
    const val=t(el.dataset.t);
    if(val!==undefined)el.innerHTML=val;
  });
  const input=document.getElementById('q');if(input)input.placeholder=label('Search article titles, disciplines or authors','ابحث في العناوين والتخصصات والباحثين');
  return true;
 }catch(error){
  console.error('Publishing display update failed:',error);
  try{sessionStorage.setItem('ujorh-pub-last-error',String(error?.message||error).slice(0,160));}catch(_error){}
  lang='en';dark=false;document.documentElement.lang='en';document.documentElement.dir='ltr';document.body.classList.remove('dark');
  saveSetting('uj-pub-lang','en');saveSetting('uj-pub-theme','light');
  return false;
 }
}
function date(s){const d=new Date(s+'T12:00:00');return d.toLocaleDateString(lang==='ar'?'ar-JO':'en-GB',{year:'numeric',month:'short',day:'numeric'})}
function status(p){return p.status==='certified'?label('Illustratively certified','اعتماد توضيحي'):label('Preprint · not peer reviewed','مسودة · غير محكمة')}
function pubTitle(p){return lang==='ar'?p.title_ar:p.title}
function showLibrary(){const q=(document.getElementById('q').value||'').trim().toLowerCase();const active=document.querySelector('.filter.active');const statusFilter=active?active.dataset.filter:'all';const list=papers.filter(p=>(statusFilter==='all'||p.status===statusFilter)&&[p.title,p.title_ar,p.authors,p.field,p.topic,p.abstract].join(' ').toLowerCase().includes(q));document.getElementById('count').textContent=label(`${list.length} fictional publication ${list.length===1?'record':'records'}`,`${list.length} سجلات نشر افتراضية`);document.getElementById('papers').innerHTML=list.length?list.map(p=>`<article class="pub-card"><div class="card-top"><span class="field-chip">${esc(p.field)}</span><span class="state ${p.status}">${esc(status(p))}</span></div><h3><a href="article.html?id=${encodeURIComponent(p.id)}">${esc(pubTitle(p))}</a></h3><p>${esc(p.summary)}</p><div class="card-authors">${esc(p.authors)} · ${date(p.date)}</div><div class="card-bottom"><b class="grade ${p.status!=='certified'?'disabled':''}">${p.status==='certified'?label('ILLUSTRATIVE GRADE ','درجة افتراضية ')+esc(p.grade):label('NOT CERTIFIED','غير معتمد')}</b><a href="article.html?id=${encodeURIComponent(p.id)}">${label('Read article →','اقرأ المقالة ←')}</a></div></article>`).join(''):`<div class="notfound">${label('No matching sample articles.','لا توجد نتائج مطابقة.')}</div>`;}
function makeFigure(p){if(!p.figure)return '';return `<figure class="figbox"><strong>${label('Illustrative figure','شكل توضيحي')}</strong>${p.figure.items.map(([name,v])=>`<div class="bar-row"><span>${esc(name)}</span><div class="bar-track"><i style="width:${Math.min(100,Math.max(0,Number(v)))}%"></i></div><b>${v}</b></div>`).join('')}<figcaption>${esc(p.figure.caption)}</figcaption></figure>`;}
function renderArticle(p){document.title=pubTitle(p)+' | Open Research Hub';document.getElementById('crumbTitle').textContent=label('Article record','سجل المقالة');const html=`<section class="article-hero"><div class="titleline"><span class="field-chip">${esc(p.field)} · ${esc(p.kind)}</span><span class="state ${p.status}">${esc(status(p))}</span></div><h1>${esc(pubTitle(p))}</h1><div class="authorline">${esc(p.authors)}</div><p class="affiliations">${esc(p.affiliations)}</p><div class="article-meta"><span>${label('Record','المعرف')}<b>${esc(p.id)}</b></span><span>${label('Date','التاريخ')}<b>${date(p.date)}</b></span><span>${label('Version','النسخة')}<b>${esc(p.version)}</b></span><span>${label('DOI','المعرف الرقمي')}<b>${label('Not assigned · demo','غير مخصص · نموذج')}</b></span></div><div class="article-actions"><a class="action primary" href="pdfs/${esc(p.slug)}.pdf" download>${label('↓ Download article PDF','↓ تنزيل المقالة PDF')}</a><button class="action" id="copyCitation">${label('Copy sample citation','نسخ الاستشهاد التوضيحي')}</button><button class="action" onclick="window.print()">${label('Print / Save','طباعة / حفظ')}</button></div><div class="inline-notice"><strong>${label('Demonstration only.','عرض توضيحي فقط.')}</strong> ${label('This record contains invented research, authors, grading and citation counts. It has not been reviewed by real experts or published by the University of Jordan.','هذا السجل يضم أبحاثاً وباحثين ودرجات واستشهادات افتراضية، ولم يخضع لتحكيم حقيقي ولم تنشره الجامعة الأردنية.')}</div></section>
<div class="article-columns"><article class="article-content"><div class="article-tabs" role="tablist" aria-label="Article information"><button class="active" data-tab="text" role="tab" aria-selected="true">${label('Full text','النص الكامل')}</button><button data-tab="assessment" role="tab" aria-selected="false">${label('Scientific assessment','التقييم العلمي')}</button><button data-tab="reviews" role="tab" aria-selected="false">${label('Peer reviews','التحكيم')}</button><button data-tab="updates" role="tab" aria-selected="false">${label('Versions & impact','الإصدارات والأثر')}</button></div>
<div class="article-panel" id="panel-text" role="tabpanel"><h2>${label('Abstract','الملخص')}</h2><p class="abstract">${esc(lang==='ar'?p.abstract_ar:p.abstract)}</p><div class="keyword-set">${p.keywords.map(k=>`<span>${esc(k)}</span>`).join('')}</div><p class="disclaimer-small">${label('All names, data and findings on this page are fabricated for interface demonstration.','كل الأسماء والبيانات والنتائج في هذه الصفحة افتراضية لأغراض العرض.')}</p>${p.sections.map(([name,body],i)=>`<section><h2>${esc(lang==='ar'&&i===0?'المقدمة / '+name:name)}</h2><p>${esc(body)}</p></section>${i===2?makeFigure(p):''}`).join('')}<div class="refs"><h2>${label('References','المراجع')}</h2>${p.references.map(r=>`<p>${esc(r)}</p>`).join('')}</div></div>
<div class="article-panel" id="panel-assessment" role="tabpanel" hidden><h2>${label('Transparent scientific assessment','التقييم العلمي الشفاف')}</h2><p>${label('A future editorial assessment would document evidence quality and the reasons for each rating. All scores below are invented to illustrate the proposed interface.','يتيح النظام المقترح تسجيل جودة الأدلة وتبرير كل درجة. جميع الدرجات التالية افتراضية للتوضيح.')}</p>${p.status==='certified'?`<div class="keyword-set"><span>${label('Example grade','درجة افتراضية')}: ${esc(p.grade)}</span><span>${label('Human review: simulated','تحكيم بشري: محاكاة')}</span></div>${Object.entries(p.scores).map(([k,v])=>`<div class="score-item"><div class="score-item-head"><span>${esc(k)}</span><strong>${v}/100</strong></div><div class="score-track"><i style="width:${v}%"></i></div></div>`).join('')}`:`<p class="review-empty">${label('This preprint has not received any scientific grade or independent peer review.','هذه المسودة لم تحصل على درجة علمية ولم تخضع لتحكيم مستقل.')}</p>`}<div class="citation-box">${label('Certification is separate from public availability. An attractive manuscript page does not establish that the science is reliable.','الاعتماد العلمي منفصل عن الإتاحة العامة؛ ولا يعني حسن عرض المقالة صحة نتائجها.')}</div></div>
<div class="article-panel" id="panel-reviews" role="tabpanel" hidden><h2>${label('Open review record','سجل التحكيم المفتوح')}</h2><p>${label('In a live system, authorized reviewer reports and author replies could be shared according to the journal’s consent and editorial policies.','يمكن إتاحة تقارير المحكمين وردود المؤلفين في النظام الحقيقي وفق سياسة النشر والموافقات المطلوبة.')}</p>${p.reviewers.length?p.reviewers.map(([name,body])=>`<div class="review-item"><b>${esc(name)}</b><p>${esc(body)}</p></div>`).join(''):`<div class="review-empty">${label('No expert reviews. This is an unreviewed example preprint.','لا توجد مراجعات خبراء. هذه مسودة توضيحية غير محكمة.')}</div>`}<p class="disclaimer-small">${label('No review on this page was written by a real peer reviewer.','لم يكتب أي تقرير هنا محكم علمي فعلي.')}</p></div>
<div class="article-panel" id="panel-updates" role="tabpanel" hidden><h2>${label('Publication history','تاريخ النشر')}</h2>${p.timeline.map(([when,what])=>`<div class="version-item"><strong>${esc(when)}</strong><p>${esc(what)}</p></div>`).join('')}<h2>${label('Post-publication assessment','التقييم بعد النشر')}</h2><p>${label('Citation impact, independent replication and expert commentary would be updated separately from the original methodological evaluation. Values below are only simulated UI examples.','تتجدد بيانات الاستشهاد والتكرار وتعليقات الخبراء بصورة مستقلة عن التقييم المنهجي الأصلي. جميع القيم أدناه افتراضية.')}</p><div class="citation-box">${label('Simulated citations','استشهادات افتراضية')}: ${p.citations} · ${label('Simulated replications','تكرارات افتراضية')}: ${p.replications}</div></div></article>
<aside class="article-sidebar"><div class="sidebar-card"><h3>${label('Scientific status','الحالة العلمية')}</h3><span class="state ${p.status}">${esc(status(p))}</span><div style="margin-top:18px"><div class="side-label">${label('Illustrative expert grade','درجة توضيحية')}</div><div class="side-score">${p.status==='certified'?esc(p.grade):'—'}</div></div><div class="small-muted">${label('Not a real certification','ليس اعتماداً علمياً فعلياً')}</div></div><div class="sidebar-card"><h3>${label('Article activity · simulated','نشاط المقالة · افتراضي')}</h3><div class="metric-row"><span>${label('Reads / downloads','القراءات / التنزيلات')}</span><b>${p.downloads}</b></div><div class="metric-row"><span>${label('Citations','الاستشهادات')}</span><b>${p.citations}</b></div><div class="metric-row"><span>${label('Peer reviews','التحكيم')}</span><b>${p.reviews}</b></div><div class="metric-row"><span>${label('Independent replications','التكرارات المستقلة')}</span><b>${p.replications}</b></div><p class="small-muted">${label('Demo counters, not live analytics.','مؤشرات افتراضية وليست بيانات فعلية.')}</p></div><div class="sidebar-card"><h3>${label('Transparency','الشفافية')}</h3><p class="small-muted">${label('Full text and PDF remain accessible. Grades and later impact are separately displayed. Private submissions are never published automatically.','يتاح النص الكامل وPDF، وتعرض الدرجة العلمية والأثر لاحقاً كل على حدة. التقديمات الخاصة لا تنشر تلقائياً.')}</p><a href="./" style="color:#0d957a;font-weight:800;font-size:12px">${label('← Return to library','→ العودة إلى المكتبة')}</a></div></aside></div>`;
document.getElementById('article').innerHTML=html;
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b?'true':'false');});document.querySelectorAll('.article-panel').forEach(el=>el.hidden=el.id!=='panel-'+b.dataset.tab);}));
document.getElementById('copyCitation').addEventListener('click',async()=>{const c=`${p.authors} (${p.date.slice(0,4)}). ${p.title}. Open Research Hub demonstration record ${p.id}. Fictional article; not a scholarly citation.`;try{await navigator.clipboard.writeText(c);document.getElementById('copyCitation').textContent=label('Copied ✓','تم النسخ ✓');setTimeout(()=>document.getElementById('copyCitation').textContent=label('Copy sample citation','نسخ الاستشهاد التوضيحي'),2000)}catch{window.prompt(label('Copy sample citation','انسخ الاستشهاد التوضيحي'),c)}});
}
function attach(){document.getElementById('language').addEventListener('click',()=>{lang=lang==='en'?'ar':'en';if(!setUI())return;saveSetting('uj-pub-lang',lang);if(pathIsArticle){const p=papers.find(p=>p.id===new URLSearchParams(location.search).get('id'));if(p)renderArticle(p);}else showLibrary();});document.getElementById('theme').addEventListener('click',()=>{dark=!dark;if(setUI())saveSetting('uj-pub-theme',dark?'dark':'light');});if(!pathIsArticle){document.getElementById('q').addEventListener('input',showLibrary);document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));showLibrary();}));}}
async function init(){setUI();attach();try{const r=await fetch('assets/papers.json',{cache:'no-store'});if(!r.ok)throw new Error(r.status);papers=await r.json();if(pathIsArticle){const p=papers.find(p=>p.id===new URLSearchParams(location.search).get('id'));if(p)renderArticle(p);else document.getElementById('article').innerHTML='<div class="notfound"><h2>Article not found</h2><a href="./">Return to research library ↗</a></div>';}else showLibrary()}catch(e){const target=document.getElementById(pathIsArticle?'article':'papers');if(target)target.innerHTML=`<div class="notfound">${label('Publication records could not be loaded. Check the uploaded files and reload.','تعذر تحميل سجلات النشر. تأكد من رفع الملفات ثم أعد التحميل.')}</div>`;console.error('Publication records load error',e)}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
